import React from 'react';
import { useAppContext } from '../context/AppContext';

function BookCard({ book }) {
  const { addToCart, addToWishlist } = useAppContext();

  const coverUrl = book.cover_i
    ? `https://covers.openlibrary.org/b/id/${book.cover_i}-M.jpg`
    : 'https://via.placeholder.com/150x220?text=No+Cover';

  return (
    <div className="book-card">
      <img src={coverUrl} alt={book.title} className="book-cover" />
      <h3>{book.title}</h3>
      <p><strong>Author:</strong> {book.author_name?.join(', ') || 'Unknown'}</p>
      <p><strong>Published:</strong> {book.first_publish_year || 'N/A'}</p>
      <button onClick={() => addToCart(book)}>Add to Cart</button>
      <button onClick={() => addToWishlist(book)}>Add to Wishlist</button>
    </div>
  );
}

export default BookCard;
